/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

//--------------------------------------------------------------------------//

Boolean can_usr_tx_normal( Can_Dev_Id dev_id , Can_Msg *can_msg , TskTimeout timeout )
{
	Boolean ret          ;
	Boolean do_tx = TRUE ; 

	os_res_request( can_usr[dev_id].tx_res , 0 );
	{
		while( do_tx )
		{					
			ret = can_tx( can_usr[dev_id].tx_can_fast , can_msg , timeout) ; 

			if( !ret )
			{
				if( (++can_usr[dev_id].err_cnt_fast ) > CAN_USR_FAST_ERROR_MAX ) 
				{
					can_usr_controller_reset( dev_id );

					ATOMIC( can_usr[dev_id].err_cnt_fast = 0 ) ; 

					do_tx = FALSE ; 
				}
			}
			else
			{
				do_tx = FALSE ; 

				ATOMIC( can_usr[dev_id].err_cnt_fast = 0 ) ; 
			}
		}									
	}
	os_res_release( can_usr[dev_id].tx_res );

	return ret ;
}		

